  "admin.compliance.title": "Compliance posture",
  "admin.compliance.subtitle": "Honest summary of what Curf does today, what's coming, and what we don't do yet. Use this as the canonical answer for security questionnaires.",
  "admin.compliance.section.today": "What we do today",
  "admin.compliance.section.inProgress": "In progress (next 90 days)",
  "admin.compliance.section.gaps": "What we don't do yet — be honest with your reviewer",
  "admin.compliance.section.surface": "Surface area",
  "admin.compliance.item.tenantIsolation.title": "Tenant isolation at every layer",
  "admin.compliance.item.tenantIsolation.body": "Every API enforces a tenantId filter through requireUser + tenantWhere. A Prisma row leak would require a code review failure on every multi-tenant model — the audit log captures any cross-tenant probe attempt.",
  "admin.compliance.item.secretsEncryption.title": "Encryption at rest for secrets",
  "admin.compliance.item.secretsEncryption.body": "API keys, SaaS connector tokens (Stripe / HubSpot / Slack bot tokens), and the per-tenant LLM provider key are AES-256-GCM encrypted via lib/secrets.ts before storage. Plaintext never lands on disk.",
  "admin.compliance.item.webhookHmac.title": "HMAC signature verification on inbound webhooks",
  "admin.compliance.item.webhookHmac.body": "Slack /events + interactivity, lake ingest tokens, and embed tokens all verify HMAC signatures with constant-time comparison. Replay window is 5 minutes for Slack.",
  "admin.compliance.item.auditLog.title": "Append-only audit log",
  "admin.compliance.item.auditLog.body": "Every security-meaningful action (signin, role change, data-source create, share-token mint, lake schema mutation, public-app publish) writes one row to the AuditEvent model. Never updated, never deleted from the app.",
  "admin.compliance.item.lakeBackups.title": "Daily lake backups + point-in-time restore",
  "admin.compliance.item.lakeBackups.body": "Lake tables are snapshotted nightly to compressed local files. Free 30 days / Team 90 / Business 365. Manual snapshots get a 365-day floor regardless of tier. Restore takes a pre-restore safety snapshot first so a bad restore is reversible.",
  "admin.compliance.item.lakeRls.title": "Row-level access control on lake tables",
  "admin.compliance.item.lakeRls.body": "Every lake table can be tenant-wide, restricted to specific role slugs, or owner-only (private). Hidden tables don't even surface in the catalog list — same status code as 'not found' so existence is concealed.",
  "admin.compliance.item.schemaMigrations.title": "Schema migrations with audit trail",
  "admin.compliance.item.schemaMigrations.body": "Add / rename / drop column on lake tables emit dedicated audit events. The runner refreshes the cached schemaJson immediately so report renderers don't operate on stale shapes.",
  "admin.compliance.item.noThirdPartyAi.title": "AI runs on Curf AI, or on your own key",
  "admin.compliance.item.noThirdPartyAi.body": "Ask Curf, Auto-Curf, watcher suggestions and the chart caption layer run on Curf AI — a model provider Curf contracts, listed on the public subprocessors page — unless this workspace connects its own provider under Tenant Settings → LLM, in which case requests are made under your own agreement with that provider and never reach Curf's. Self-hosted instances can disable the AI path entirely with CURF_LLM=off; heuristic fallbacks still produce useful output.",
  "admin.compliance.item.exportDeletion.title": "One-click data export + deletion",
  "admin.compliance.item.exportDeletion.body": "Tenant admins can request a tenant-wide CSV/Parquet export (Phase 2 feature, in progress) and a hard-delete of any lake table. GDPR DSR workflows route through these primitives.",
  "admin.compliance.item.pdpaRecord.title": "PDPA processing record",
  "admin.compliance.item.pdpaRecord.body": "Tenant admins can declare a summary processing record — data categories, purpose, legal basis, retention — at Admin -> Tenant. A single tenant-wide record, not a full multi-activity register.",
  "admin.compliance.item.restReadOnly.title": "Read-only REST connections",
  "admin.compliance.item.restReadOnly.body": "A REST connection can be marked read-only, which blocks any report query against it that isn't a GET request. SQL-kind connections (Postgres, MySQL, Snowflake, BigQuery, SQLite) are already unconditionally SELECT-only.",
  "admin.compliance.item.offsiteBackup.title": "Backup off-site to S3 / Spaces",
  "admin.compliance.item.offsiteBackup.body": "Today's snapshots live on the same disk as the live database. Phase 3 ships a tier-aware S3 (or DigitalOcean Spaces) sink so a disk failure doesn't take backups with it.",
  "admin.compliance.item.piiTagging.title": "Column-level PII tagging + redaction",
  "admin.compliance.item.piiTagging.body": "Tag a lake column as PII / financial / health at upload; non-privileged role queries see the column redacted at the runner. Useful for shared dashboards where the owner sees full data and viewers see masked.",
  "admin.compliance.item.costTelemetry.title": "Cost telemetry per tenant",
  "admin.compliance.item.costTelemetry.body": "Storage bytes, query CPU, ingestion volume, LLM token spend — surfaced on /admin/usage so admins can see (and we can bill against) actual consumption.",
  "admin.compliance.item.soc2.title": "Formal SOC 2 Type II audit",
  "admin.compliance.item.soc2.body": "We've built the controls; we haven't run them through a third-party auditor yet. SOC 2 typically takes 6 months and is best-timed against an enterprise contract. Email security@curf.ai to start that conversation.",
  "admin.compliance.item.hipaa.title": "HIPAA Business Associate Agreement",
  "admin.compliance.item.hipaa.body": "No BAA today. Healthcare workloads should wait for Phase 3 of the data-layer roadmap (column-level encryption with customer-managed keys, residency choice). See ROADMAP-DATA-LAYER.md.",
  "admin.compliance.item.residency.title": "Multi-region data residency",
  "admin.compliance.item.residency.body": "Single region per Curf install today. EU / APAC / US regional pinning ships in Phase 3.",
  "admin.compliance.item.ssoCustomIdp.title": "SSO with custom IdPs (Okta / Azure AD)",
  "admin.compliance.item.ssoCustomIdp.body": "Built-in SSO covers Google + GitHub. Custom IdP support is gated on demand — happy to prioritize for a paid pilot.",
  "admin.compliance.surface.intro": "Models touched by sensitive data:",
  "admin.compliance.surface.connectionStrings": "(connection strings)",
  "admin.compliance.surface.botTokens": "(bot tokens)",
  "admin.compliance.surface.outro": "Every one is tenant-scoped via Prisma {code} + runtime ACL.",
  "admin.compliance.surface.roadmapPre": "Read the full data-layer roadmap at",
  "admin.compliance.surface.roadmapPost": "for everything in flight.",
  "admin.compliance.questionsIntro": "Questions a security questionnaire usually doesn't reach — happy to answer in writing:",
  "admin.compliance.q.subprocessors": "Specific subprocessors (AWS for hosting, your selected LLM provider, Stripe for billing)",
