  "landing.testimonial1.body": "ผมใช้เวลาแค่ 30 วินาทีพิมพ์พรอมป์ แต่ใช้เวลาตั้ง 20 นาทีกว่าจะเลิกสงสัยตัวเลข — เพราะทุกตัวเลขมีแฮชให้ตรวจสอบได้จริง",
