  "landing.testimonial2.attribution": "ฟินเทค · ผู้จัดการฝ่ายวิเคราะห์ข้อมูล",
  "landing.testimonial3.body": "ในที่สุดเราก็มีแดชบอร์ดที่ผู้ควบคุมบัญชีไว้ใจได้ในการตรวจสอบด้านการปฏิบัติตามกฎระเบียบ สแนปช็อตย้อนเวลาช่วยปิดการสนทนากับผู้ตรวจสอบที่เคยยืดเยื้อเป็นสัปดาห์ให้จบได้เร็วขึ้นมาก",
