  "upgradeLock.tagline.growth": "สร้างรายงานได้ไม่จำกัด ตั้งเวลาส่งรายงาน และลิงก์แชร์",
  "upgradeLock.tagline.business": "รวมทุกอย่างในแพ็กเกจ Growth บวกคำบรรยายกราฟด้วย AI, ระบบเฝ้าระวัง, บันทึกการตรวจสอบ (audit log), OIDC แบบกำหนดเอง",
